sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    try {
        var reqResponse = [];
        // Intialize input data in body
        var equipment, requester, quantity;

        // body
        var result = request.body.data;

		// Validation phase
        // In this condition we will validate if the equipment is string, has been entered,
		//  and 
		// also if only the value is ['Laptop', 'mobile' , 'monitor'], This condition made in POSTMAN Script
        if (
            typeof result.equipment !== 'string' ||
            !result.equipment
        ) {
            response.setStatus(400); // Bad request
            return {
                error:  "Invalid data, equipment should Required in String type..! "
            };
        } else
            equipment = result.equipment;

        if (
            typeof result.requester !== 'string' || 
            !result.requester) {
            response.setStatus(400); // Bad request
            return {
                error: "Invalid data, requester should Required in String type..!"
            };
        } else
            requester = result.requester;

        if (
            typeof result.quantity !== 'number' ||
            !result.quantity) {
            response.setStatus(400); // Bad request
            return {
                error: "Invalid data, quantity should Required in number type..!"
            };
        } else
            quantity = result.quantity;


        // insert New record stage
        var equipReqObj = new GlideRecord('x_1850489_mini_p_0_equipments_requests');

        var userObj = new GlideRecord('sys_user');

        equipReqObj.initialize();

        equipReqObj.equipment = equipment;
        equipReqObj.quantity = quantity;
        // Pricing of each equipment item
        if (equipment == 'Laptop')
            equipReqObj.price = 300;
        else if (equipment == 'mobile')
            equipReqObj.price = 150;
        else
            equipReqObj.price = 200;
        equipReqObj.total_price = equipReqObj.quantity * equipReqObj.price;
        // Determine if the requester name is found in the table or not
        userObj.addQuery('user_name', requester);
        userObj.query();
        if (userObj.next()) {
            equipReqObj.requester = requester;

            // If the requester has manager field with null value (blank), so will put "hussien.m" as manager
            var defaultManagerSysId = '41c03f4253c1f210829a70c0a0490ee2';
            // "sys_id" of "hussien.m" 

            // Case of requester manager is blank
            if (userObj.manager.nil) {
                // Add hussien.m to the manager
                equipReqObj.manager = defaultManagerSysId;
            }
            // otherwise
            else {
                // Set value of manager in equipment table
                equipReqObj.manager = userObj.manager;
            }
        } else {
            response.setStatus(400); // Bad request
            response.setBody({
                error: "Invalid requester..!"
            });
        }

        var equipSysId = equipReqObj.insert();
        if (!equipSysId) {
            response.setStatus(500);
            return {
                error: "Faild to create Equipment Request "
            };
        }
        response.setStatus(201); // created successfully
        return {
            message: "Equipment Request created successfully :)",
            sys_id: equipSysId,
        };
    } catch (error) {
        // Error recogonize
        response.setStatus(500); 
        return {
            error: error.message
        };
    }


})(request, response);
